import re, pathlib
mods={}
for p in pathlib.Path('AlgebraicJacobian').rglob('*.lean'):
    name='AlgebraicJacobian'+str(p)[len('AlgebraicJacobian'):].replace('/','.')[:-5]
    mods[name]=re.findall(r'^import\s+(AlgebraicJacobian[\w.]*)', p.read_text(), flags=re.M)
Q='AlgebraicJacobian.Picard.QuotScheme'
# BFS shortest path
from collections import deque
def path(src):
    dq=deque([(src,[src])]); seen={src}
    while dq:
        m,pth=dq.popleft()
        if m==Q: return pth
        for i in mods.get(m,[]):
            if i not in seen: seen.add(i); dq.append((i,pth+[i]))
    return None
for s in ['AlgebraicJacobian.Picard.PicEtSubcanonical','AlgebraicJacobian.Picard.PicEtSeparated','AlgebraicJacobian.Picard.EtaleFieldCover']:
    p=path(s)
    print(s.split('.')[-1], '->', ' -> '.join(x.split('.')[-1] for x in p) if p else 'NONE')
